const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function localISO(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
const iso=()=>localISO(new Date());
function nowStamp(d=new Date()){const y=localISO(d),h=String(d.getHours()).padStart(2,'0'),m=String(d.getMinutes()).padStart(2,'0'),s=String(d.getSeconds()).padStart(2,'0');return `${y} ${h}:${m}:${s}`}
function dateOnly(v){return String(v||'').slice(0,10)}
function dateObj(s){return new Date((dateOnly(s)||iso())+'T12:00:00')}
function daysBetween(a,b){return Math.ceil((dateObj(b)-dateObj(a))/86400000)}
function addDays(date,n){const d=dateObj(date);d.setDate(d.getDate()+n);return localISO(d)}
function fmtStamp(v){if(!v)return '';const s=String(v).replace('T',' ');return s.length>=19?s.slice(0,19):s}
function recordTimeText(x,fallback=''){if(!x)return '';const created=x.createdAt||fallback||x.date||'',updated=x.updatedAt||'',migrated=x.migratedAt||'';if(created&&updated&&fmtStamp(created)!==fmtStamp(updated))return `创建 ${fmtStamp(created)} · 更新 ${fmtStamp(updated)}`;if(created)return `记录 ${fmtStamp(created)}`;if(migrated)return `历史记录迁移 ${fmtStamp(migrated)}`;return '历史记录 · 原版本未保存时间'}
function auditHTML(x,fallback=''){return `<div class="meta time-meta">⏱ ${esc(recordTimeText(x,fallback))}</div>`}
function auditFields(old,fallback=''){const now=nowStamp();return {createdAt:old?.createdAt||now,updatedAt:now,migratedAt:old?.migratedAt||''}}

