function renderHome(){
 const total=totalWords(),goal=Number(state.settings.totalWordGoal||80000),p=pct(total,goal),dleft=Math.max(0,daysBetween(iso(),state.settings.defenseDate)),todayGoal=dailyGoal(iso()),tg=todayGoalProgress(),wl=workloadSummary(),hl=healthLevel();
 const unresolved=state.problems.filter(x=>x.status!=='已解决').length,todoPending=state.todos.filter(x=>!x.done).length,h=healthSummary(),last=lastWriting(),top3=todayPriorityItems(3);
 $('#view-home').innerHTML=`
 <div class="hero"><div class="hero-top"><div><div class="eyebrow">论文总进度</div><div class="big">${fmt(total)} <small>/ ${fmt(goal)} 字</small></div></div><div style="font-weight:800">${p}%</div></div><div class="progress"><span style="width:${p}%"></span></div><div class="hero-note">${state.settings.hideThesisTitle?'论文题目已隐藏':esc(state.settings.thesisTitle)}</div></div>
 <div class="stats4"><div class="stat editable" onclick="todayGoalForm()" title="点按设置今日目标"><div class="label">今日目标</div><div class="num">${fmt(todayGoal)}<span class="unit">字</span></div></div><div class="stat"><div class="label">今日已写</div><div class="num">${fmt(todayWords())}<span class="unit">字</span></div></div><div class="stat"><div class="label">连续写作</div><div class="num">${streak()}<span class="unit">天</span></div></div><div class="stat"><div class="label">答辩倒计时</div><div class="num">${dleft}<span class="unit">天</span></div></div></div>
 <div class="card today-progress-card" onclick="todayGoalForm()"><div class="top"><div><div class="title">今日完成度</div><div class="meta">${fmt(tg.words)} / ${fmt(tg.goal)} 字${tg.remain?` · 还差 ${fmt(tg.remain)} 字`:' · 今日目标已完成'}</div></div><div class="pct">${tg.pct}%</div></div><div class="small-progress"><span style="width:${tg.pct}%"></span></div></div>
 ${last?`<div class="card continue-card" onclick="continueLastWriting()"><div class="row"><div><div class="title">继续上次写作</div><div class="meta">${esc(chapterTitle(last.chapterId))}${last.sectionId?' · '+esc(sectionTitle(last.chapterId,last.sectionId)):''} · 上次 +${fmt(last.words)} 字</div></div><span class="chip warn">继续 ›</span></div></div>`:''}
 <div class="section-title"><h2>今日三件事</h2><span class="sub">自动按紧急程度排序</span></div><div class="priority-list">${top3.length?top3.map((x,i)=>`<div class="card" onclick="${x.open}"><div class="row-start"><div class="priority-no">${i+1}</div><div style="flex:1;min-width:0"><div class="row"><div class="title">${esc(x.title)}</div><span class="chip blue">${esc(x.type)}</span></div><div class="meta">${esc(x.meta)}</div></div></div></div>`).join(''):'<div class="card"><div class="title">今天没有紧急事项</div><div class="meta">可以从“开始写作”或“今日写作路线”安排下一步。</div></div>'}</div>
 <div class="section-title"><h2>论文健康度</h2><span class="health-status ${hl.cls}">${hl.level}</span></div>
 <div class="health"><div class="hcard"><div class="hlabel">近14日日均</div><div class="hnum">${fmt(h.pred.avg)} 字/天</div></div><div class="hcard"><div class="hlabel">预计达到目标</div><div class="hnum ${h.late?'badtxt':'goodtxt'}">${h.pred.date==='—'?'暂无足够数据':formatDateCN(h.pred.date)}</div></div><div class="hcard"><div class="hlabel">高优先级未闭环</div><div class="hnum ${h.high?'badtxt':'goodtxt'}">${h.high} 项</div></div><div class="hcard"><div class="hlabel">逾期待办</div><div class="hnum ${h.overdue?'badtxt':'goodtxt'}">${h.overdue} 项</div></div></div>
 <div class="card"><div class="title">距提交的剩余工作量</div><div class="workload-line"><div><b>${fmt(wl.remain)}</b><span>剩余字数</span></div><div><b>${wl.days===null?'—':wl.days}</b><span>距提交天数</span></div><div><b>${wl.days===null?'—':fmt(wl.required)}</b><span>建议日均字数</span></div></div></div>
 <div class="section-title"><h2>快速开始</h2><span class="sub">论文核心动作</span></div><div class="quick"><button onclick="go('focus')"><div class="iconbox">写</div><strong>开始写作</strong><span>专注计时 + 自动登记</span></button><button onclick="go('problems')"><div class="iconbox">问</div><strong>记录问题</strong><span>${unresolved} 个问题待闭环</span></button><button onclick="go('resources');resourceTab='todos'"><div class="iconbox">办</div><strong>论文待办</strong><span>${todoPending} 项待完成</span></button><button onclick="resourceTab='literature';go('resources')"><div class="iconbox">文</div><strong>文献卡片</strong><span>${typeof v68Counts!=='undefined'&&v68Counts.literature!=null?v68Counts.literature:state.literature.length} 篇已录入</span></button><button onclick="go('resources');resourceTab='meetings'"><div class="iconbox">会</div><strong>导师会议</strong><span>${typeof v68Counts!=='undefined'&&v68Counts.meetings!=null?v68Counts.meetings:state.meetings.length} 次已记录</span></button><button onclick="resourceTab='finalcheck';go('resources')"><div class="iconbox">检</div><strong>送审检查</strong><span>${state.finalChecks.filter(x=>x.done).length}/${state.finalChecks.length} 已完成</span></button></div>
 ${urgentBlock()}<div class="section-title"><h2>最近动态</h2><span class="sub">所有模块自动汇总</span></div>${recentActivity()}`;
}
function urgentBlock(){
 let items=[];
 state.todos.filter(x=>!x.done&&x.due).forEach(x=>items.push({score:daysBetween(iso(),x.due)<0?100:40,date:x.due,title:x.title,meta:`待办 · ${x.priority||'中'}优先级`,open:`todoForm('${x.id}')`,danger:daysBetween(iso(),x.due)<0}));
 state.problems.filter(x=>x.status!=='已解决'&&x.priority==='高').forEach(x=>items.push({score:80,date:x.createdAt,title:x.title,meta:'高优先级问题未解决',open:`problemDetail('${x.id}')`,danger:true}));
 state.feedback.filter(x=>x.status!=='已完成'&&x.priority==='高').forEach(x=>items.push({score:75,date:x.createdAt,title:x.title,meta:'高优先级修改未完成',open:`feedbackForm('${x.id}')`,danger:true}));
 items.sort((a,b)=>b.score-a.score||String(a.date).localeCompare(String(b.date)));if(!items.length)return '';
 return `<div class="section-title"><h2>需要优先处理</h2><span class="sub">${items.length} 项</span></div>${items.slice(0,5).map(x=>`<div class="card alert-card ${x.danger?'danger':''}" onclick="${x.open}"><div class="row"><div><div class="title">${esc(x.title)}</div><div class="meta">${esc(x.meta)}</div></div>${x.date?dueBadge(x.date,false):''}</div></div>`).join('')}`;
}
function recentActivity(){
 let items=[];
 const add=(x,title,meta,fallback='')=>items.push({time:x.updatedAt||x.createdAt||fallback||x.date||'',title,meta});
 state.writingLogs.forEach(x=>add(x,`写作 +${x.words} 字`,x.note||chapterTitle(x.chapterId),x.date));
 state.problems.forEach(x=>add(x,`问题：${x.title}`,`${x.status} · ${x.type||'未分类'}`));
 state.feedback.forEach(x=>add(x,`修改：${x.title}`,`${x.status} · ${x.source||'未注明来源'}`));
 state.todos.forEach(x=>add(x,`待办：${x.title}`,x.done?'已完成':'待完成'));
 state.versions.forEach(x=>add(x,`版本：${x.name}`,`${x.stage||'版本记录'} · ${fmt(x.wordCount||0)}字`,x.date));
 state.defense.forEach(x=>add(x,`答辩：${x.title}`,x.status||'待准备'));
 state.meetings.forEach(x=>add(x,`导师会议：${x.topic}`,x.actions?'已记录下一步行动':'会议记录',x.date));
 items.sort((a,b)=>String(b.time).localeCompare(String(a.time)));if(!items.length)return `<div class="empty">还没有记录。今天写第一笔，就从这里开始。</div>`;
 return items.slice(0,7).map(x=>`<div class="card"><div class="title">${esc(x.title)}</div><div class="meta">${esc(x.meta)}</div><div class="meta time-meta">⏱ ${esc(fmtStamp(x.time)||'历史记录')}</div></div>`).join('');
}

function writingRouteForm(id){const x=state.writingRoutes.find(v=>v.id===id)||{date:iso(),chapterId:state.settings.defaultChapterId||state.chapters[0]?.id||'',sectionId:'',title:'',targetWords:0,done:false,order:todayRoutes().length+1};const opts=[];state.chapters.forEach(c=>{opts.push(`<option value="${c.id}::" ${x.chapterId===c.id&&!x.sectionId?'selected':''}>${esc(c.title)}（整章）</option>`);(c.sections||[]).forEach(s=>opts.push(`<option value="${c.id}::${s.id}" ${x.chapterId===c.id&&x.sectionId===s.id?'selected':''}>${esc(c.title)} · ${esc(s.title)}</option>`))});openSheet(`<h3>${id?'编辑写作路线':'安排今日写作路线'}</h3><div class="field"><label>日期</label><input id="f-route-date" type="date" value="${esc(x.date||iso())}"></div><div class="field"><label>章节 / 小节</label><select id="f-route-section">${opts.join('')}</select></div><div class="field"><label>今天要完成什么</label><input id="f-route-title" value="${esc(x.title||'')}" placeholder="例如：写完4.2评价结果解释"></div><div class="form2"><div class="field"><label>目标字数（可选）</label><input id="f-route-words" type="number" value="${x.targetWords||0}"></div><div class="field"><label>顺序</label><input id="f-route-order" type="number" value="${x.order||1}"></div></div><div class="field"><label>状态</label><select id="f-route-done"><option value="0" ${!x.done?'selected':''}>待完成</option><option value="1" ${x.done?'selected':''}>已完成</option></select></div><div class="actions">${id?`<button class="btn danger" onclick="removeItem('writingRoutes','${id}')">删除</button>`:''}<button class="btn primary" onclick="saveWritingRoute('${id||''}')">保存</button></div>`)}
function saveWritingRoute(id){const old=state.writingRoutes.find(x=>x.id===id),parts=$('#f-route-section').value.split('::'),times=auditFields(old,$('#f-route-date').value);const v={id:id||uid(),date:$('#f-route-date').value,chapterId:parts[0]||'',sectionId:parts[1]||'',title:$('#f-route-title').value.trim(),targetWords:+$('#f-route-words').value||0,order:+$('#f-route-order').value||1,done:$('#f-route-done').value==='1',...times};if(!v.chapterId)return alert('请选择章节');const i=state.writingRoutes.findIndex(x=>x.id===id);if(i>=0)state.writingRoutes[i]=v;else state.writingRoutes.push(v);closeSheet();save()}
function toggleWritingRoute(id,done){const x=state.writingRoutes.find(v=>v.id===id);if(x){x.done=done;x.updatedAt=nowStamp();x.completedAt=done?(x.completedAt||x.updatedAt):'';save()}}
function writingRouteHTML(){const rows=todayRoutes();return `<div class="card"><div class="route-head"><div><div class="title">今日写作路线</div><div class="meta">先安排小节，再进入专注写作</div></div><button class="tiny-btn" onclick="writingRouteForm()">+ 安排</button></div>${rows.length?rows.map(x=>`<div class="route-item"><input type="checkbox" ${x.done?'checked':''} onchange="toggleWritingRoute('${x.id}',this.checked)"><div class="route-main" onclick="writingRouteForm('${x.id}')"><div class="title">${esc(x.title||routeLabel(x))}</div><div class="meta">${esc(routeLabel(x))}${x.targetWords?' · 目标 '+fmt(x.targetWords)+' 字':''}</div></div>${!x.done?`<div class="route-actions"><button class="tiny-btn" onclick="startRoute('${x.id}')">开始</button></div>`:''}</div>`).join(''):'<div class="empty" style="padding:16px 6px">今天还没安排写作路线。可按 1～3 个小节拆开推进。</div>'}</div>`}

function chapterDetail(id){const c=state.chapters.find(x=>x.id===id);if(!c)return;const p=pct(c.currentWords,c.targetWords),tasks=c.tasks||[];openSheet(`<h3>${esc(c.title)}</h3><div class="row"><div class="meta">${fmt(c.currentWords)} / ${fmt(c.targetWords)} 字 · ${esc(c.status)}</div><b style="color:var(--navy)">${p}%</b></div><div class="small-progress"><span style="width:${p}%"></span></div>${auditHTML(c)}${c.notes?`<div class="detail-block"><b>章节备注 / 待补内容</b><p>${esc(c.notes)}</p></div>`:''}<div class="section-title"><h2>章节任务</h2><button class="pill-btn" style="padding:7px 10px" onclick="chapterTaskForm('${id}')">+ 任务</button></div>${tasks.length?tasks.map(t=>`<div class="chapter-task"><div class="checkrow"><input type="checkbox" ${t.done?'checked':''} onchange="toggleChapterTask('${id}','${t.id}',this.checked)"><div style="flex:1" onclick="chapterTaskForm('${id}','${t.id}')"><div class="title">${esc(t.title)}</div><div class="meta">${esc(t.priority||'中')}优先级${t.sectionId?' · '+esc(sectionTitle(id,t.sectionId)):''}${t.due?' · '+esc(t.due):''}</div></div></div></div>`).join(''):'<div class="empty" style="padding:12px">还没有章节任务，可拆成“补图、补文献、写结果、核对格式”等。</div>'}<div class="section-title"><h2>小节清单</h2><button class="pill-btn" style="padding:7px 10px" onclick="sectionForm('${id}')">+ 小节</button></div>${(c.sections||[]).map(s=>`<div class="section-mini" onclick="event.stopPropagation();sectionForm('${id}','${s.id}')"><div class="row"><div style="min-width:0"><div class="title">${esc(s.title)}</div><div class="meta">${fmt(s.currentWords||0)} / ${fmt(s.targetWords||0)} 字 · ${esc(s.status||'')} · 完成条件 ${sectionCheckPct(s)}%</div></div><b>${pct(s.currentWords,s.targetWords)}%</b></div><div class="small-progress"><span style="width:${pct(s.currentWords,s.targetWords)}%"></span></div>${sectionChecksHTML(s)}${auditHTML(s)}</div>`).join('')||'<div class="empty" style="padding:14px">还没有小节。可细化到 1.1、1.2、1.3 级别管理。</div>'}<div class="actions"><button class="btn soft" onclick="chapterForm('${id}')">编辑章节</button><button class="btn primary" onclick="closeSheet();writingLogForm(null,'${id}')">给本章记字数</button></div>`) }

function chapterTaskForm(cid,tid){const c=state.chapters.find(x=>x.id===cid);if(!c)return;const x=(c.tasks||[]).find(t=>t.id===tid)||{title:'',sectionId:'',priority:'中',due:'',done:false,notes:''};openSheet(`<h3>${tid?'编辑章节任务':'新增章节任务'} · ${esc(c.title)}</h3><div class="field"><label>任务</label><input id="f-task-title" value="${esc(x.title||'')}" placeholder="例如：补4.2结果图说明"></div><div class="form2"><div class="field"><label>关联小节</label><select id="f-task-sec"><option value="">整章</option>${(c.sections||[]).map(s=>`<option value="${s.id}" ${x.sectionId===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div><div class="field"><label>优先级</label><select id="f-task-priority">${['高','中','低'].map(v=>`<option ${x.priority===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>截止日期</label><input id="f-task-due" type="date" value="${esc(x.due||'')}"></div><div class="field"><label>说明</label><textarea id="f-task-notes">${esc(x.notes||'')}</textarea></div><div class="field"><label>状态</label><select id="f-task-done"><option value="0" ${!x.done?'selected':''}>待完成</option><option value="1" ${x.done?'selected':''}>已完成</option></select></div><div class="actions">${tid?`<button class="btn danger" onclick="removeChapterTask('${cid}','${tid}')">删除</button>`:''}<button class="btn primary" onclick="saveChapterTask('${cid}','${tid||''}')">保存</button></div>`)}
function saveChapterTask(cid,tid){const c=state.chapters.find(x=>x.id===cid);if(!c)return;c.tasks=c.tasks||[];const old=c.tasks.find(x=>x.id===tid),done=$('#f-task-done').value==='1',times=auditFields(old),now=nowStamp();const v={id:tid||uid(),title:$('#f-task-title').value.trim(),sectionId:$('#f-task-sec').value,priority:$('#f-task-priority').value,due:$('#f-task-due').value,notes:$('#f-task-notes').value.trim(),done,...times,completedAt:done?(old?.completedAt||now):''};if(!v.title)return alert('请填写任务');const i=c.tasks.findIndex(x=>x.id===tid);if(i>=0)c.tasks[i]=v;else c.tasks.push(v);c.updatedAt=nowStamp();closeSheet();save()}
function toggleChapterTask(cid,tid,done){const c=state.chapters.find(x=>x.id===cid),t=c?.tasks?.find(x=>x.id===tid);if(t){t.done=done;t.updatedAt=nowStamp();t.completedAt=done?(t.completedAt||t.updatedAt):'';c.updatedAt=t.updatedAt;save()}}


function chapterForm(id){const x=state.chapters.find(v=>v.id===id)||{id:'',title:'',targetWords:0,currentWords:0,status:'未开始',notes:'',sections:[]};openSheet(`<h3>${id?'编辑章节':'新增章节'}</h3><div class="field"><label>章节名称</label><input id="f-title" value="${esc(x.title)}"></div><div class="form2"><div class="field"><label>目标字数</label><input id="f-target" type="number" value="${x.targetWords||0}"></div><div class="field"><label>当前字数</label><input id="f-current" type="number" value="${x.currentWords||0}"></div></div><div class="field"><label>状态</label><select id="f-status">${['未开始','进行中','已完成'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`)}</select></div><div class="field"><label>备注 / 待补内容</label><textarea id="f-notes">${esc(x.notes||'')}</textarea></div><div class="actions">${id?`<button class="btn danger" onclick="removeItem('chapters','${id}')">删除</button>`:''}<button class="btn primary" onclick="saveChapter('${id}')">保存</button></div>`)}
function saveChapter(id){const old=state.chapters.find(x=>x.id===id),times=auditFields(old);const v={id:id||uid(),title:$('#f-title').value.trim(),targetWords:+$('#f-target').value||0,currentWords:+$('#f-current').value||0,status:$('#f-status').value,notes:$('#f-notes').value.trim(),sections:old?.sections||[],tasks:old?.tasks||[],...times};if(!v.title)return alert('请填写章节名称');const i=state.chapters.findIndex(x=>x.id===id);if(i>=0)state.chapters[i]=v;else state.chapters.push(v);closeSheet();save()}
function sectionForm(cid,sid){const c=state.chapters.find(x=>x.id===cid);if(!c)return;const x=c.sections.find(v=>v.id===sid)||{title:'',targetWords:0,currentWords:0,status:'未开始',notes:'',checks:{text:false,figures:false,citations:false,feedback:false}},ck=Object.assign({text:false,figures:false,citations:false,feedback:false},x.checks||{});openSheet(`<h3>${sid?'编辑小节':'新增小节'} · ${esc(c.title)}</h3><div class="field"><label>小节名称</label><input id="f-title" value="${esc(x.title)}" placeholder="例如：4.2 危险性评价结果"></div><div class="form2"><div class="field"><label>目标字数</label><input id="f-target" type="number" value="${x.targetWords||0}"></div><div class="field"><label>当前字数</label><input id="f-current" type="number" value="${x.currentWords||0}"></div></div><div class="field"><label>状态</label><select id="f-status">${['未开始','进行中','已完成'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>小节完成条件</label><div class="field-checks"><label class="field-check"><input id="f-ck-text" type="checkbox" ${ck.text?'checked':''}>正文完成</label><label class="field-check"><input id="f-ck-figures" type="checkbox" ${ck.figures?'checked':''}>图表完成</label><label class="field-check"><input id="f-ck-citations" type="checkbox" ${ck.citations?'checked':''}>引文核对</label><label class="field-check"><input id="f-ck-feedback" type="checkbox" ${ck.feedback?'checked':''}>导师修改完成</label></div></div><div class="field"><label>备注</label><textarea id="f-notes">${esc(x.notes||'')}</textarea></div><div class="actions">${sid?`<button class="btn danger" onclick="removeSection('${cid}','${sid}')">删除</button>`:''}<button class="btn primary" onclick="saveSection('${cid}','${sid||''}')">保存</button></div>`) }
function saveSection(cid,sid){const c=state.chapters.find(x=>x.id===cid);if(!c)return;const old=c.sections.find(x=>x.id===sid),times=auditFields(old);const checks={text:$('#f-ck-text').checked,figures:$('#f-ck-figures').checked,citations:$('#f-ck-citations').checked,feedback:$('#f-ck-feedback').checked};const v={id:sid||uid(),title:$('#f-title').value.trim(),targetWords:+$('#f-target').value||0,currentWords:+$('#f-current').value||0,status:$('#f-status').value,notes:$('#f-notes').value.trim(),checks,...times};if(!v.title)return alert('请填写小节名称');const i=c.sections.findIndex(x=>x.id===sid);if(i>=0)c.sections[i]=v;else c.sections.push(v);c.updatedAt=nowStamp();closeSheet();save()}


function renderProblems(){
 const list=state.problems.filter(x=>problemFilter==='all'||(problemFilter==='open'?x.status!=='已解决':problemFilter==='solved'?x.status==='已解决':x.priority==='高')).sort((a,b)=>((a.status==='已解决')-(b.status==='已解决'))||((b.priority==='高')-(a.priority==='高'))||String(b.updatedAt||b.createdAt).localeCompare(String(a.updatedAt||a.createdAt)));
 const solved=state.problems.filter(x=>x.status==='已解决').length,avgSolve=averageSolveDays();
 $('#view-problems').innerHTML=`<div class="page-head"><div><h2>写作台</h2><div class="sub">问题不仅记录，还关联到小节、文献和修改任务</div></div></div>${workspaceSwitcher('problems')}<div class="section-title" style="margin-top:2px"><h2>问题记录 / 答疑</h2><span class="sub">问题 → 处理 → 结果 → 复盘</span></div><div class="tabs"><button class="${problemFilter==='all'?'active':''}" onclick="setProblemFilterV67('all')">全部 ${state.problems.length}</button><button class="${problemFilter==='open'?'active':''}" onclick="setProblemFilterV67('open')">未闭环 ${state.problems.length-solved}</button><button class="${problemFilter==='solved'?'active':''}" onclick="setProblemFilterV67('solved')">已解决 ${solved}</button><button class="${problemFilter==='high'?'active':''}" onclick="setProblemFilterV67('high')">高优先级</button></div>${list.map(x=>`<div class="card" onclick="problemDetail('${x.id}')"><div class="row"><div class="title">${esc(x.title)}</div>${statusChip(x.status)}</div><div class="meta">${esc(x.chapter||'未指定章节')} · ${esc(x.type||'未分类')} · ${esc(x.priority||'中')}优先级${x.status!=='已解决'?' · 已卡 '+blockerDays(x)+' 天':''}</div>${x.relatedSectionKey?`<div class="assoc">关联：${esc(relatedSectionText(x.relatedSectionKey))}</div>`:''}${x.description?`<div class="meta">${esc(x.description).slice(0,95)}${x.description.length>95?'…':''}</div>`:''}${auditHTML(x)}</div>`).join('')||'<div class="empty">暂时没有问题记录。遇到卡点就记下来，解决后补上结果和复盘。</div>'}<div class="kpi-strip"><div class="kpi"><b>${state.problems.length}</b><span>问题总数</span></div><div class="kpi"><b>${solved}</b><span>已解决</span></div><div class="kpi"><b>${avgSolve===null?'—':avgSolve}</b><span>平均解决天数</span></div></div>`;
}
function averageSolveDays(){const v=state.problems.filter(x=>x.status==='已解决'&&x.createdAt&&x.resolvedAt).map(x=>Math.max(0,daysBetween(x.createdAt,x.resolvedAt)));return v.length?Math.round(v.reduce((a,b)=>a+b,0)/v.length*10)/10:null}
function problemForm(id){const x=state.problems.find(v=>v.id===id)||{title:'',chapter:'',type:'结构逻辑',description:'',status:'未解决',method:'',resolution:'',lesson:'',priority:'中',source:'自己发现',evidence:'',createdAt:iso(),resolvedAt:'',relatedSectionKey:'',relatedLiteratureId:'',relatedFeedbackId:''};let secOpts='<option value="">不关联小节</option>',litOpts='<option value="">不关联文献</option>',fbOpts='<option value="">不关联修改任务</option>';state.chapters.forEach(c=>(c.sections||[]).forEach(s=>{const k=`${c.id}::${s.id}`;secOpts+=`<option value="${k}" ${x.relatedSectionKey===k?'selected':''}>${esc(c.title)} · ${esc(s.title)}</option>`}));state.literature.forEach(v=>litOpts+=`<option value="${v.id}" ${x.relatedLiteratureId===v.id?'selected':''}>${esc(v.title)}</option>`);state.feedback.filter(v=>v.status!=='已完成'||v.id===x.relatedFeedbackId).forEach(v=>fbOpts+=`<option value="${v.id}" ${x.relatedFeedbackId===v.id?'selected':''}>${esc(v.title)}</option>`);openSheet(`<h3>${id?'编辑问题':'记录今天遇到的问题'}</h3><div class="field"><label>问题标题</label><input id="f-title" value="${esc(x.title)}" placeholder="例如：第4章图表说明怎么写"></div><div class="form2"><div class="field"><label>所属章节（文字）</label><input id="f-chapter" value="${esc(x.chapter||'')}" placeholder="第4章"></div><div class="field"><label>问题类型</label><select id="f-type">${['结构逻辑','文字表达','图表规范','数据分析','文献引用','格式排版','方法设计','导师意见','答辩准备','其他'].map(s=>`<option ${x.type===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="field"><label>关联到具体小节</label><select id="f-related-section">${secOpts}</select></div><div class="form2"><div class="field"><label>来源</label><select id="f-source">${['自己发现','导师提出','同学讨论','文献启发','规范要求','答辩/评审','其他'].map(s=>`<option ${x.source===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>优先级</label><select id="f-priority">${['高','中','低'].map(s=>`<option ${x.priority===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="form2"><div class="field"><label>关联文献</label><select id="f-related-lit">${litOpts}</select></div><div class="field"><label>关联导师修改</label><select id="f-related-feedback">${fbOpts}</select></div></div><div class="field"><label>问题描述</label><textarea id="f-desc">${esc(x.description||'')}</textarea></div><div class="field"><label>状态</label><select id="f-status">${['未解决','处理中','已解决','需继续跟进'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>解决方式 / 处理过程</label><textarea id="f-method">${esc(x.method||'')}</textarea></div><div class="field"><label>依据 / 相关资料</label><textarea id="f-evidence" placeholder="可记文献、规范、导师原话或数据依据">${esc(x.evidence||'')}</textarea></div><div class="field"><label>最终解决结果</label><textarea id="f-resolution">${esc(x.resolution||'')}</textarea></div><div class="field"><label>经验总结 / 下次怎么做</label><textarea id="f-lesson">${esc(x.lesson||'')}</textarea></div><div class="actions">${id?`<button class="btn danger" onclick="removeItem('problems','${id}')">删除</button>`:''}<button class="btn primary" onclick="saveProblem('${id||''}')">保存</button></div>`) }
function saveProblem(id){const old=state.problems.find(x=>x.id===id),status=$('#f-status').value,times=auditFields(old),now=nowStamp();const v={id:id||uid(),title:$('#f-title').value.trim(),chapter:$('#f-chapter').value.trim(),type:$('#f-type').value,source:$('#f-source').value,description:$('#f-desc').value.trim(),status,priority:$('#f-priority').value,method:$('#f-method').value.trim(),evidence:$('#f-evidence').value.trim(),resolution:$('#f-resolution').value.trim(),lesson:$('#f-lesson').value.trim(),relatedSectionKey:$('#f-related-section').value,relatedLiteratureId:$('#f-related-lit').value,relatedFeedbackId:$('#f-related-feedback').value,...times,resolvedAt:status==='已解决'?(old?.resolvedAt||now):''};if(!v.title)return alert('请填写问题标题');const i=state.problems.findIndex(x=>x.id===id);if(i>=0)state.problems[i]=v;else state.problems.push(v);closeSheet();save()}
function problemDetail(id){const x=state.problems.find(v=>v.id===id);if(!x)return;const lit=state.literature.find(v=>v.id===x.relatedLiteratureId),fb=state.feedback.find(v=>v.id===x.relatedFeedbackId);openSheet(`<h3>${esc(x.title)}</h3><div class="row"><div class="meta">${esc(x.chapter||'未指定章节')} · ${esc(x.type||'未分类')} · ${esc(x.priority||'中')}优先级${x.status!=='已解决'?' · 已卡 '+blockerDays(x)+' 天':''}</div>${statusChip(x.status)}</div><div class="meta">来源：${esc(x.source||'未记录')}</div>${x.relatedSectionKey?`<div class="assoc">关联小节：${esc(relatedSectionText(x.relatedSectionKey))}</div>`:''}${lit?`<div class="assoc">关联文献：${esc(lit.title)}</div>`:''}${fb?`<div class="assoc">关联修改：${esc(fb.title)}</div>`:''}${auditHTML(x)}${x.resolvedAt?`<div class="meta time-meta">✓ 解决 ${esc(fmtStamp(x.resolvedAt))}</div>`:''}${x.description?`<div class="detail-block"><b>问题描述</b><p>${esc(x.description)}</p></div>`:''}${x.method?`<div class="detail-block"><b>处理过程</b><p>${esc(x.method)}</p></div>`:''}${x.evidence?`<div class="detail-block"><b>依据 / 相关资料</b><p>${esc(x.evidence)}</p></div>`:''}${x.resolution?`<div class="detail-block"><b>解决结果</b><p>${esc(x.resolution)}</p></div>`:''}${x.lesson?`<div class="detail-block"><b>复盘总结</b><p>${esc(x.lesson)}</p></div>`:''}<div class="actions"><button class="btn soft" onclick="closeSheet();problemForm('${id}')">编辑</button>${x.status!=='已解决'?`<button class="btn primary" onclick="markSolved('${id}')">标记已解决</button>`:`<button class="btn primary" onclick="reopenProblem('${id}')">重新打开</button>`}</div>`) }
function markSolved(id){const x=state.problems.find(v=>v.id===id);if(x){x.status='已解决';x.resolvedAt=nowStamp();x.updatedAt=nowStamp();x.createdAt=x.createdAt||x.updatedAt}closeSheet();save()}
function reopenProblem(id){const x=state.problems.find(v=>v.id===id);if(x){x.status='需继续跟进';x.resolvedAt='';x.updatedAt=nowStamp();x.createdAt=x.createdAt||x.updatedAt}closeSheet();save()}

function resourceTabTitle(){return ({literature:'文献卡片',feedback:'导师修改',todos:'论文待办',meetings:'导师会议',figures:'图表管理',milestones:'时间节点',versions:'版本管理',finalcheck:'送审检查',defense:'答辩准备'})[resourceTab]||'资料流程'}
function statsHintText(){return ({today:'看今天的产出和当天目标完成情况。',week:'看这一周的写作节奏、效率和闭环情况。',month:'看本月推进状态，并可下钻到具体某一周。',year:'看全年累计与阶段性变化。',all:'看总览和历史月份分布。'})[statsRange]||''}

function tagsHTML(tags){const arr=String(tags||'').split(/[,，\s]+/).filter(Boolean);return arr.length?`<div>${arr.slice(0,6).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}

function weekStart(date=statsAnchor){const d=dateObj(date),dow=(d.getDay()+6)%7;d.setDate(d.getDate()-dow);return localISO(d)}
function weekData(anchor=statsAnchor){const arr=[],mon=dateObj(weekStart(anchor));for(let i=0;i<7;i++){const d=new Date(mon);d.setDate(mon.getDate()+i);const k=localISO(d);arr.push({date:k,label:'一二三四五六日'[i],value:wordsOn(k)})}return arr}
function monthBuckets(date=statsAnchor){const d0=dateObj(date),y=d0.getFullYear(),m=d0.getMonth(),days=new Date(y,m+1,0).getDate(),b=[0,0,0,0,0,0];state.writingLogs.forEach(x=>{const d=dateObj(x.date);if(d.getFullYear()===y&&d.getMonth()===m){b[Math.min(5,Math.floor((d.getDate()-1)/5))]+=Number(x.words||0)}});return b.map((v,i)=>({label:i<5?`${i*5+1}-${i*5+5}`:`26-${days}`,value:v}))}
function yearData(year=dateObj(statsAnchor).getFullYear()){return Array.from({length:12},(_,m)=>({label:`${m+1}月`,value:state.writingLogs.filter(x=>{const d=dateObj(x.date);return d.getFullYear()===year&&d.getMonth()===m}).reduce((s,x)=>s+Number(x.words||0),0)}))}
function todaySessions(date=statsAnchor){return state.writingLogs.filter(x=>x.date===date).sort((a,b)=>String(a.createdAt||'').localeCompare(String(b.createdAt||''))).map((x,i)=>({label:`${i+1}`,value:Number(x.words||0),title:x.note||chapterTitle(x.chapterId)}))}
function barChart(data,labelPrefix=''){const max=Math.max(1,...data.map(x=>x.value));return `<div class="bar-chart">${data.map((x,i)=>`<div class="bar-wrap"><div class="bar ${i===data.length-1?'gold':''}" style="height:${Math.max(2,x.value/max*110)}px"><span class="bar-val">${x.value}</span></div><div class="bar-label">${esc(labelPrefix+x.label)}</div></div>`).join('')}</div>`}
function rangeDates(range,anchor=statsAnchor){const now=dateObj(anchor);if(range==='today')return [localISO(now),localISO(now)];if(range==='week'){const a=weekStart(anchor);return [a,addDays(a,6)]}if(range==='month')return [`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`,localISO(new Date(now.getFullYear(),now.getMonth()+1,0,12))];if(range==='year')return [`${now.getFullYear()}-01-01`,`${now.getFullYear()}-12-31`];return ['0000-01-01','9999-12-31']}
function inDateRange(v,a,b){const d=dateOnly(v);return !!d&&d>=a&&d<=b}
function rangeSummary(range,anchor=statsAnchor){const [a,b]=rangeDates(range,anchor),logs=state.writingLogs.filter(x=>x.date>=a&&x.date<=b),words=logs.reduce((s,x)=>s+Number(x.words||0),0),mins=logs.reduce((s,x)=>s+Number(x.minutes||0),0),problems=state.problems.filter(x=>inDateRange(x.createdAt,a,b)).length,solved=state.problems.filter(x=>inDateRange(x.resolvedAt,a,b)).length,todos=state.todos.filter(x=>x.done&&inDateRange(x.completedAt||x.updatedAt,a,b)).length,feedback=state.feedback.filter(x=>x.status==='已完成'&&inDateRange(x.completedAt||x.updatedAt,a,b)).length,meetings=state.meetings.filter(x=>x.date>=a&&x.date<=b).length;return {words,mins,sessions:logs.length,problems,solved,todos,feedback,meetings}}
function previousAnchor(range,anchor=statsAnchor){const d=dateObj(anchor);if(range==='today')d.setDate(d.getDate()-1);else if(range==='week')d.setDate(d.getDate()-7);else if(range==='month'){d.setDate(1);d.setMonth(d.getMonth()-1)}else if(range==='year')d.setFullYear(d.getFullYear()-1);return localISO(d)}
function compareText(cur,prev){cur=Number(cur||0);prev=Number(prev||0);if(prev===0&&cur===0)return {text:'—',cls:'delta-flat'};if(prev===0&&cur>0)return {text:'新增',cls:'delta-up'};const v=Math.round((cur-prev)/Math.abs(prev)*100);if(v>0)return {text:`↑ ${v}%`,cls:'delta-up'};if(v<0)return {text:`↓ ${Math.abs(v)}%`,cls:'delta-down'};return {text:'→ 0%',cls:'delta-flat'}}
function periodGoal(range=statsRange,anchor=statsAnchor){const daily=Math.max(0,Number(state.settings.dailyWordGoal||0)),weekly=Math.max(0,Number(state.settings.weeklyWordGoal||daily*7)),d=dateObj(anchor);if(range==='today')return dailyGoal(dateOnly(anchor));if(range==='week')return weekly;if(range==='month'){const days=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();return Math.round(weekly*days/7)}if(range==='year')return Math.round(weekly*365.25/7);return Math.max(0,Number(state.settings.totalWordGoal||0))}
function periodWordsForGoal(range=statsRange,s=null){if(range==='all')return totalWords();return (s||rangeSummary(range)).words}
function comparisonHTML(range=statsRange,anchor=statsAnchor,current=null){if(range==='all')return '';const prevAnchor=previousAnchor(range,anchor),prev=rangeSummary(range,prevAnchor),cur=current||rangeSummary(range,anchor),a=compareText(cur.words,prev.words),b=compareText(cur.mins,prev.mins),c=compareText(cur.sessions,prev.sessions),label=range==='today'?'前一天':range==='week'?'上一周':range==='month'?'上个月':'上一年';return `<div class="analysis-card"><div class="head"><div><div class="title">环比变化</div><div class="meta">与${label}相比</div></div><div class="meta">${esc(periodLabel(range,anchor))}</div></div><div class="compare-grid"><div class="compare-cell"><b class="${a.cls}">${a.text}</b><span>写作字数</span></div><div class="compare-cell"><b class="${b.cls}">${b.text}</b><span>专注时长</span></div><div class="compare-cell"><b class="${c.cls}">${c.text}</b><span>写作会话</span></div></div></div>`}
function goalProgressHTML(range=statsRange,anchor=statsAnchor,current=null){const goal=periodGoal(range,anchor),done=periodWordsForGoal(range,current),raw=goal?Math.round(done/goal*100):0,p=Math.min(100,Math.max(0,raw)),remain=Math.max(0,goal-done),name=range==='all'?'论文总目标':range==='today'?'单日目标':range==='week'?'每周目标':range==='month'?'月度参考目标':'年度参考目标';return `<div class="analysis-card"><div class="head"><div><div class="title">目标完成情况</div><div class="meta">${name}</div></div><b style="color:var(--gold)">${goal?raw+'%':'未设置'}</b></div><div class="goal-line"><div><b>${fmt(done)}</b><span> 字已完成</span></div><span>${goal?`目标 ${fmt(goal)} 字 · ${remain?`还差 ${fmt(remain)} 字`:'已达成'}`:'请先在“我的”设置写作目标'}</span></div><div class="small-progress"><span style="width:${p}%"></span></div>${range==='month'||range==='year'?'<div class="analysis-note">月度/年度参考目标由“每周目标”按周期天数折算，仅用于观察写作节奏。</div>':''}</div>`}
function bestWritingDay(range=statsRange,anchor=statsAnchor){const [a,b]=rangeDates(range,anchor),map={};state.writingLogs.forEach(x=>{if(x.date>=a&&x.date<=b)map[x.date]=(map[x.date]||0)+Number(x.words||0)});const arr=Object.entries(map).sort((x,y)=>y[1]-x[1]);return arr[0]||null}
function efficiencyHTML(range=statsRange,anchor=statsAnchor,current=null){const s=current||rangeSummary(range,anchor),avgWords=s.sessions?Math.round(s.words/s.sessions):0,avgMins=s.sessions?Math.round(s.mins/s.sessions):0,wph=s.mins?Math.round(s.words/(s.mins/60)):0,best=bestWritingDay(range,anchor);return `<div class="section-title"><h2>写作效率</h2><span class="sub">由字数与写作时长自动计算</span></div><div class="insight-grid"><div class="insight-cell"><div class="k">平均每次写作</div><div class="v">${fmt(avgWords)} 字</div><div class="d">${s.sessions} 次会话</div></div><div class="insight-cell"><div class="k">平均每小时</div><div class="v">${fmt(wph)} 字</div><div class="d">按记录分钟数换算</div></div><div class="insight-cell"><div class="k">平均每次时长</div><div class="v">${fmt(avgMins)} 分</div><div class="d">单次专注节奏</div></div><div class="insight-cell"><div class="k">最高产的一天</div><div class="v">${best?fmt(best[1])+' 字':'—'}</div><div class="d">${best?best[0]:'暂无写作记录'}</div></div></div>`}
function stampMs(v){if(!v)return NaN;const s=String(v).trim().replace(' ','T');const t=new Date(s.length===10?s+'T12:00:00':s).getTime();return Number.isFinite(t)?t:NaN}
function closeTimeText(items,endField){const vals=items.map(x=>{const a=stampMs(x.createdAt),b=stampMs(x[endField]||x.updatedAt);return Number.isFinite(a)&&Number.isFinite(b)&&b>=a?(b-a)/3600000:null}).filter(v=>v!==null);if(!vals.length)return '暂无';const avg=vals.reduce((s,x)=>s+x,0)/vals.length;return avg<24?`${Math.round(avg)} 小时`:`${(avg/24).toFixed(1)} 天`}
function closureHTML(range=statsRange,anchor=statsAnchor){const [a,b]=rangeDates(range,anchor),problemNew=state.problems.filter(x=>inDateRange(x.createdAt,a,b)).length,problemSolvedItems=state.problems.filter(x=>inDateRange(x.resolvedAt,a,b)),problemOpen=state.problems.filter(x=>x.status!=='已解决').length,feedbackNew=state.feedback.filter(x=>inDateRange(x.createdAt,a,b)).length,feedbackDoneItems=state.feedback.filter(x=>x.status==='已完成'&&inDateRange(x.completedAt||x.updatedAt,a,b)),feedbackOpen=state.feedback.filter(x=>x.status!=='已完成').length;return `<div class="section-title"><h2>问题与修改闭环</h2><span class="sub">周期变化 + 当前积压</span></div><div class="closure-row"><div class="closure-box" onclick="go('problems')"><div class="name">问题闭环</div><div class="nums">${problemNew} 新增 · ${problemSolvedItems.length} 解决</div><div class="desc">当前未解决 ${problemOpen} 项 · 平均解决 ${closeTimeText(problemSolvedItems,'resolvedAt')}</div></div><div class="closure-box" onclick="resourceTab='feedback';go('resources')"><div class="name">导师修改</div><div class="nums">${feedbackNew} 新增 · ${feedbackDoneItems.length} 完成</div><div class="desc">当前未完成 ${feedbackOpen} 项 · 平均完成 ${closeTimeText(feedbackDoneItems,'completedAt')}</div></div></div>`}
function chapterProgressHTML(range=statsRange,anchor=statsAnchor){const [a,b]=rangeDates(range,anchor),adds={};state.writingLogs.forEach(x=>{if(x.date>=a&&x.date<=b&&x.chapterId)adds[x.chapterId]=(adds[x.chapterId]||0)+Number(x.words||0)});return `<div class="section-title"><h2>章节进度</h2><span class="sub">当前完成度 · 本周期新增字数</span></div><div class="chapter-progress-list">${state.chapters.map(c=>{const p=pct(c.currentWords,c.targetWords),add=adds[c.id]||0;return `<div class="chapter-progress-item" onclick="chapterDetail('${c.id}')"><div class="row"><div class="title">${esc(c.title)}</div><b style="color:var(--navy)">${p}%</b></div><div class="small-progress"><span style="width:${p}%"></span></div><div class="chapter-meta">${fmt(c.currentWords)} / ${fmt(c.targetWords)} 字${add?` · 本周期 +${fmt(add)} 字`:''}</div></div>`}).join('')||'<div class="empty">暂无章节数据</div>'}</div>`}
function statsInsightsHTML(range=statsRange,anchor=statsAnchor,current=null){return `<div class="section-title"><h2>分析洞察</h2><span class="sub">目标、环比与效率</span></div>${goalProgressHTML(range,anchor,current)}${comparisonHTML(range,anchor,current)}${efficiencyHTML(range,anchor,current)}${closureHTML(range,anchor)}${chapterProgressHTML(range,anchor)}`}

function periodLabel(range=statsRange,anchor=statsAnchor){const [a,b]=rangeDates(range,anchor),d=dateObj(anchor);if(range==='today')return formatDateCN(a);if(range==='week')return `${a.replaceAll('-','.')} — ${b.replaceAll('-','.')}`;if(range==='month')return `${d.getFullYear()}年${d.getMonth()+1}月`;if(range==='year')return `${d.getFullYear()}年`;return '累计全部记录'}



function periodNavHTML(){if(statsRange==='all')return '';return `<div class="period-nav"><button onclick="moveStatsPeriod(-1)">‹ 上一${statsRange==='today'?'天':statsRange==='week'?'周':statsRange==='month'?'月':'年'}</button><div class="period-center"><b>${esc(periodLabel())}</b><input type="date" value="${esc(statsAnchor)}" onchange="setStatsAnchor(this.value)" aria-label="选择历史日期"></div><button onclick="moveStatsPeriod(1)">下一${statsRange==='today'?'天':statsRange==='week'?'周':statsRange==='month'?'月':'年'} ›</button></div><div class="meta" style="text-align:center;margin:-5px 0 11px">可选择任意历史日期；周/月统计会自动定位到该日期所在周期</div>`}
function monthWeeksHTML(anchor=statsAnchor){const d=dateObj(anchor),first=new Date(d.getFullYear(),d.getMonth(),1,12),last=new Date(d.getFullYear(),d.getMonth()+1,0,12);let ws=dateObj(weekStart(localISO(first))),rows=[],i=1;while(ws<=last){const a=localISO(ws),b=addDays(a,6),s=rangeSummary('week',a);rows.push(`<div class="section-mini week-jump" onclick="statsRange='week';statsAnchor='${a}';renderStats()"><div class="row"><div><div class="title">第 ${i} 周 · ${a.slice(5).replace('-','/')}—${b.slice(5).replace('-','/')}</div><div class="meta">${fmt(s.words)} 字 · ${fmt(s.mins)} 分钟 · ${s.sessions} 次写作 · ${s.problems} 个新增问题</div></div><span class="chev">›</span></div></div>`);ws.setDate(ws.getDate()+7);i++}return `<div class="section-title"><h2>这个月的每周记录</h2><span class="sub">点某周查看完整明细</span></div>${rows.join('')}`}
function monthlyHistoryHTML(limit=12){const base=dateObj(iso()),rows=[];base.setDate(1);for(let i=0;i<limit;i++){const d=new Date(base);d.setMonth(base.getMonth()-i);const a=localISO(d),s=rangeSummary('month',a);rows.push(`<div class="section-mini" onclick="statsRange='month';statsAnchor='${a}';calendarCursor=dateObj('${a}');calendarCursor.setDate(1);renderStats()"><div class="row"><div><div class="title">${d.getFullYear()}年${d.getMonth()+1}月</div><div class="meta">${fmt(s.words)} 字 · ${s.sessions} 次写作 · ${fmt(s.mins)} 分钟 · 完成待办 ${s.todos} 项</div></div><span class="badge-num">${s.sessions}</span></div></div>`)}return `<div class="section-title"><h2>历史月份</h2><span class="sub">最近 ${limit} 个月，可继续进入某周</span></div>${rows.join('')}`}

function allStatsHTML(){const solved=state.problems.filter(x=>x.status==='已解决').length,feedbackDone=state.feedback.filter(x=>x.status==='已完成').length,todoDone=state.todos.filter(x=>x.done).length,figDone=state.figures.filter(x=>x.status==='已完成').length,defenseDone=state.defense.filter(x=>x.status==='已完成').length,focusMinutes=state.focusLogs.reduce((s,x)=>s+Number(x.minutes||0),0),checks=state.finalChecks.filter(x=>x.done).length,eng=state.literature.filter(x=>x.language==='英文').length,cited=state.literature.filter(x=>x.status==='已引用').length,types={};state.problems.forEach(x=>types[x.type||'未分类']=(types[x.type||'未分类']||0)+1);const tmax=Math.max(1,...Object.values(types));return `<div class="section-title"><h2>累计总览</h2><span class="sub">从开始使用到现在</span></div><div class="summary-grid"><div class="summary"><div class="l">累计字数</div><div class="n">${fmt(totalWords())}</div></div><div class="summary"><div class="l">累计专注</div><div class="n">${fmt(focusMinutes)}<small>分</small></div></div><div class="summary"><div class="l">问题已解决</div><div class="n">${solved}<small> / ${state.problems.length}</small></div></div><div class="summary"><div class="l">修改已完成</div><div class="n">${feedbackDone}<small> / ${state.feedback.length}</small></div></div><div class="summary"><div class="l">待办已完成</div><div class="n">${todoDone}<small> / ${state.todos.length}</small></div></div><div class="summary"><div class="l">图表已完成</div><div class="n">${figDone}<small> / ${state.figures.length}</small></div></div><div class="summary"><div class="l">文献 / 英文 / 已引</div><div class="n">${state.literature.length}<small> / ${eng} / ${cited}</small></div></div><div class="summary"><div class="l">导师会议</div><div class="n">${state.meetings.length}<small>次</small></div></div><div class="summary"><div class="l">论文版本</div><div class="n">${state.versions.length}<small>版</small></div></div><div class="summary"><div class="l">答辩准备</div><div class="n">${defenseDone}<small> / ${state.defense.length}</small></div></div><div class="summary"><div class="l">定稿检查</div><div class="n">${checks}<small> / ${state.finalChecks.length}</small></div></div><div class="summary"><div class="l">进度预测</div><div class="n" style="font-size:14px">${predictedDate().date==='—'?'暂无':formatDateCN(predictedDate().date)}</div></div></div><div class="section-title"><h2>问题类型分布</h2></div>${Object.keys(types).length?Object.entries(types).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="card"><div class="row"><div class="title">${esc(k)}</div><b>${v}</b></div><div class="small-progress"><span style="width:${v/tmax*100}%"></span></div></div>`).join(''):'<div class="empty">记录问题后会自动统计。</div>'}<div class="section-title"><h2>章节完成度</h2></div>${state.chapters.map(c=>`<div class="card"><div class="row"><div class="title">${esc(c.title)}</div><b>${pct(c.currentWords,c.targetWords)}%</b></div><div class="small-progress"><span style="width:${pct(c.currentWords,c.targetWords)}%"></span></div>${auditHTML(c)}</div>`).join('')}`}
function calendarHTML(anchor=null){const cursor=anchor?dateObj(anchor):calendarCursor,y=cursor.getFullYear(),m=cursor.getMonth(),first=new Date(y,m,1,12),last=new Date(y,m+1,0,12),start=(first.getDay()+6)%7,days=last.getDate(),vals=[];for(let d=1;d<=days;d++){const k=localISO(new Date(y,m,d,12));vals.push(wordsOn(k))}const max=Math.max(1,...vals);let cells=Array.from({length:start},()=>'<div class="cal-day empty"></div>');for(let d=1;d<=days;d++){const k=localISO(new Date(y,m,d,12)),v=wordsOn(k),r=v/max,lv=v===0?'':r<=.25?'lv1':r<=.5?'lv2':r<=.75?'lv3':'lv4';cells.push(`<button class="cal-day ${lv} ${k===iso()?'today':''}" onclick="dayDetail('${k}')">${d}${v?'<span class="cal-dot"></span>':''}</button>`)}const arrows=anchor?'':`<button onclick="moveCalendar(-1)">‹</button>`;const arrows2=anchor?'':`<button onclick="moveCalendar(1)">›</button>`;return `<div class="chart-card"><div class="calendar-head">${arrows}<div class="title">${y}年${m+1}月 · 写作日历</div>${arrows2}</div><div class="calendar-grid">${'一二三四五六日'.split('').map(x=>`<div class="cal-week">${x}</div>`).join('')}${cells.join('')}</div><div class="meta" style="margin-top:8px">颜色越深，写作字数越多。点某一天查看当天全部记录。</div></div>`}
function moveCalendar(n){calendarCursor.setMonth(calendarCursor.getMonth()+n);renderStats()}
function dayRecordListHTML(date){const logs=state.writingLogs.filter(x=>x.date===date);return logs.length?`<div class="section-title"><h2>当天写作记录</h2><span class="sub">精确记录时间</span></div>${logs.slice().sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).map(x=>`<div class="card" onclick="writingLogForm('${x.id}')"><div class="title">+${fmt(x.words)} 字 · ${esc(chapterTitle(x.chapterId))}</div><div class="meta">${fmt(x.minutes)} 分钟${x.note?' · '+esc(x.note):''}</div>${auditHTML(x,x.date)}</div>`).join('')}`:''}
function weekRecordListHTML(anchor){const [a,b]=rangeDates('week',anchor),logs=state.writingLogs.filter(x=>x.date>=a&&x.date<=b).sort((x,y)=>String(y.createdAt||y.date).localeCompare(String(x.createdAt||x.date)));return logs.length?`<div class="section-title"><h2>本周全部写作记录</h2><span class="sub">${logs.length} 次</span></div>${logs.map(x=>`<div class="card" onclick="writingLogForm('${x.id}')"><div class="row"><div class="title">${esc(x.date)} · +${fmt(x.words)} 字</div><span class="chip blue">${fmt(x.minutes)} 分</span></div><div class="meta">${esc(chapterTitle(x.chapterId))}${x.sectionId?' · '+esc(sectionTitle(x.chapterId,x.sectionId)):''}${x.note?' · '+esc(x.note):''}</div>${auditHTML(x,x.date)}</div>`).join('')}`:''}
function periodOtherRecordsHTML(range,anchor){const [a,b]=rangeDates(range,anchor),items=[],add=(type,x,title,meta,open,business='')=>{const t=x.updatedAt||x.completedAt||x.resolvedAt||x.createdAt||business||x.date||'';if(inDateRange(t||business,a,b))items.push({type,x,title,meta,open,time:t,business})};state.problems.forEach(x=>add('问题',x,x.title,`${x.status} · ${x.type||'未分类'}`,`problemDetail('${x.id}')`));state.feedback.forEach(x=>add('修改',x,x.title,`${x.status} · ${x.source||'未注明来源'}`,`feedbackForm('${x.id}')`));state.todos.forEach(x=>add('待办',x,x.title,x.done?'已完成':'待完成',`todoForm('${x.id}')`));state.literature.forEach(x=>add('文献',x,x.title,`${x.status||'待阅读'} · ${x.language||'未注明'}`,`literatureForm('${x.id}')`));state.meetings.forEach(x=>add('会议',x,x.topic,x.withWhom||'导师沟通',`meetingForm('${x.id}')`,x.date));state.figures.forEach(x=>add('图表',x,`${x.no||''} ${x.title}`.trim(),x.status||'待制作',`figureForm('${x.id}')`));state.milestones.forEach(x=>add('节点',x,x.title,x.status||'待完成',`milestoneForm('${x.id}')`,x.date));state.versions.forEach(x=>add('版本',x,x.name,x.stage||'版本记录',`versionForm('${x.id}')`,x.date));state.defense.forEach(x=>add('答辩',x,x.title,x.status||'待准备',`defenseForm('${x.id}')`));state.finalChecks.forEach(x=>add('定稿',x,x.title,x.done?'已完成':'未完成',`finalCheckForm('${x.id}')`));items.sort((x,y)=>String(y.time).localeCompare(String(x.time)));if(!items.length)return `<div class="section-title"><h2>本周其他记录</h2><span class="sub">0 项</span></div><div class="empty">这一周没有问题、文献、待办、会议等其他记录。</div>`;return `<div class="section-title"><h2>本周其他记录</h2><span class="sub">${items.length} 项 · 按最后记录时间排序</span></div>${items.map(i=>`<div class="card" onclick="${i.open}"><div class="row"><div class="title">${esc(i.title)}</div><span class="chip blue">${esc(i.type)}</span></div><div class="meta">${esc(i.meta||'')}</div>${auditHTML(i.x,i.business)}</div>`).join('')}`}
function dayDetail(date){const same=v=>dateOnly(v)===date,logs=state.writingLogs.filter(x=>x.date===date),problems=state.problems.filter(x=>same(x.createdAt)||same(x.resolvedAt)||same(x.updatedAt)),feedback=state.feedback.filter(x=>same(x.createdAt)||same(x.completedAt)||same(x.updatedAt)),todos=state.todos.filter(x=>same(x.createdAt)||same(x.completedAt)||same(x.updatedAt)),meetings=state.meetings.filter(x=>x.date===date),versions=state.versions.filter(x=>x.date===date),milestones=state.milestones.filter(x=>x.date===date);const other=[...problems.map(x=>`<div class="section-mini"><div class="title">问题：${esc(x.title)}</div><div class="meta">${esc(x.status)}</div>${auditHTML(x)}</div>`),...feedback.map(x=>`<div class="section-mini"><div class="title">修改：${esc(x.title)}</div><div class="meta">${esc(x.status)}</div>${auditHTML(x)}</div>`),...todos.map(x=>`<div class="section-mini"><div class="title">待办：${esc(x.title)}</div><div class="meta">${x.done?'已完成':'已更新'}</div>${auditHTML(x)}</div>`),...meetings.map(x=>`<div class="section-mini"><div class="title">导师会议：${esc(x.topic)}</div>${auditHTML(x,x.date)}</div>`),...versions.map(x=>`<div class="section-mini"><div class="title">论文版本：${esc(x.name)}</div>${auditHTML(x,x.date)}</div>`),...milestones.map(x=>`<div class="section-mini"><div class="title">时间节点：${esc(x.title)}</div>${auditHTML(x,x.date)}</div>`)];openSheet(`<h3>${formatDateCN(date)} · 单日详情</h3><div class="mini-grid"><div class="mini-cell"><b>${fmt(wordsOn(date))}</b><span>写作字数</span></div><div class="mini-cell"><b>${minutesOn(date)}</b><span>写作分钟</span></div><div class="mini-cell"><b>${logs.length}</b><span>写作会话</span></div></div><div class="section-title"><h2>写作记录</h2></div>${logs.map(x=>`<div class="section-mini" onclick="writingLogForm('${x.id}')"><div class="title">+${fmt(x.words)} 字 · ${esc(chapterTitle(x.chapterId))}</div><div class="meta">${x.sectionId?esc(sectionTitle(x.chapterId,x.sectionId))+' · ':''}${fmt(x.minutes)} 分钟${x.note?' · '+esc(x.note):''}</div>${auditHTML(x,x.date)}</div>`).join('')||'<div class="empty" style="padding:12px">无写作记录</div>'}<div class="section-title"><h2>其他动态</h2></div>${other.join('')||'<div class="empty" style="padding:12px">无其他动态</div>'}`)}


function quickPrivacySettings(){const s=state.settings;openSheet(`<h3>显示偏好</h3><div class="field"><label>连续写作天数</label><select id="f-countStreak"><option value="1" ${s.countStreak!==false?'selected':''}>开启</option><option value="0" ${s.countStreak===false?'selected':''}>关闭</option></select></div><div class="field"><label>首页显示论文题目</label><select id="f-hideTitle"><option value="0" ${!s.hideThesisTitle?'selected':''}>显示</option><option value="1" ${s.hideThesisTitle?'selected':''}>隐藏</option></select></div><div class="actions"><button class="btn primary" onclick="savePrivacySettings()">保存</button></div>`)}
function savePrivacySettings(){state.settings.countStreak=$('#f-countStreak').value==='1';state.settings.hideThesisTitle=$('#f-hideTitle').value==='1';state.settings.updatedAt=nowStamp();closeSheet();save()}
async function clearAppCache(){if(!confirm('刷新程序缓存不会删除论文记录。确定继续吗？'))return;try{if('caches'in window){for(const k of await caches.keys())await caches.delete(k)}const regs=await navigator.serviceWorker?.getRegistrations?.();if(regs)for(const r of regs)await r.update();alert('程序缓存已清理，即将重新加载。');location.reload()}catch(e){alert('缓存清理未完全完成，可以关闭 App 后重新打开。')}}
function showUsageHelp(){openSheet(`<h3>使用说明</h3><div class="detail-block"><b>建议工作流</b><p>1. 首页看今天优先事项和论文健康度。\n2. 写作时用“开始写作”，结束后登记字数和时长。\n3. 卡点记到“问题”，解决后补解决结果和复盘。\n4. 导师意见、文献、图表、会议、版本、答辩都放在“资料”。\n5. “记录”里可在“资料流程 / 统计分析”间切换；“我的”负责参数、备份和程序管理。</p></div><div class="detail-block"><b>数据安全</b><p>建议每周至少导出一次 JSON，并保存到 iCloud Drive 或电脑。删除网页 App、清理 Safari 网站数据或系统存储清理都可能影响本地记录。</p></div>`)}

function renderFocus(){const route=todayRoutes().find(x=>!x.done&&(focusPresetChapterId?x.chapterId===focusPresetChapterId:true)),target=focusPresetChapterId?`${chapterTitle(focusPresetChapterId)}${focusPresetSectionId?' · '+sectionTitle(focusPresetChapterId,focusPresetSectionId):''}`:(route?routeLabel(route):'未指定章节');$('#view-focus').innerHTML=`<div class="page-head"><div><h2>写作台</h2><div class="sub">专注完成后自动弹出写作登记</div></div></div>${workspaceSwitcher('focus')}<div class="section-title" style="margin-top:2px"><h2>专注写作</h2><button class="pill-btn" style="padding:8px 12px" onclick="go('home')">返回</button></div><div class="focus-wrap"><div style="font-size:12px;opacity:.75">沉浸写作计时</div><div class="focus-current">当前：${esc(target)}</div><div class="timer" id="timer">${timerText()}</div><div class="focus-controls"><button class="go" onclick="toggleFocus()">${focusRunning?'暂停':'开始专注'}</button><button class="ghost" onclick="resetFocus()">重置</button></div></div><div class="card"><div class="row"><div><div class="title">登记成果</div><div class="meta">完整专注结束时会自动弹出；也可以现在手动登记。</div></div><button class="tiny-btn" onclick="writingLogForm('',focusPresetChapterId,focusPresetSectionId)">登记</button></div></div>${writingRouteHTML()}<div class="section-title"><h2>最近写作记录</h2></div>${state.writingLogs.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,12).map(x=>`<div class="card" onclick="writingLogForm('${x.id}')"><div class="row"><div class="title">+${fmt(x.words)} 字</div><span class="chip blue">${esc(x.date)}</span></div><div class="meta">${esc(chapterTitle(x.chapterId))}${x.sectionId?' · '+esc(sectionTitle(x.chapterId,x.sectionId)):''} · ${fmt(x.minutes)} 分钟${x.note?' · '+esc(x.note):''}</div>${auditHTML(x,x.date)}</div>`).join('')||'<div class="empty">还没有写作记录。</div>'}`;}
function timerText(){const m=Math.floor(focusSeconds/60),s=focusSeconds%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function toggleFocus(){focusRunning=!focusRunning;if(focusRunning){focusTimer=setInterval(()=>{focusSeconds--;const el=$('#timer');if(el)el.textContent=timerText();if(focusSeconds<=0){clearInterval(focusTimer);focusRunning=false;navigator.vibrate?.(200);const mins=state.settings.focusMinutes,route=todayRoutes().find(x=>!x.done&&(focusPresetChapterId?x.chapterId===focusPresetChapterId:true));if(!focusPresetChapterId&&route){focusPresetChapterId=route.chapterId;focusPresetSectionId=route.sectionId||''}focusSeconds=state.settings.focusMinutes*60;renderFocus();setTimeout(()=>writingLogForm('',focusPresetChapterId,focusPresetSectionId,mins),80)}},1000)}else clearInterval(focusTimer);renderFocus()}
function resetFocus(){clearInterval(focusTimer);focusRunning=false;focusSeconds=state.settings.focusMinutes*60;renderFocus()}

function refreshSectionSelect(selected=''){const sel=$('#f-sec'),cid=$('#f-ch')?.value;if(!sel)return;const secs=state.chapters.find(x=>x.id===cid)?.sections||[];sel.innerHTML=`<option value="">不指定小节</option>`+secs.map(s=>`<option value="${s.id}" ${selected===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}
function applyWritingDelta(cid,sid,delta){const c=state.chapters.find(x=>x.id===cid),now=nowStamp();if(c){c.currentWords=Math.max(0,Number(c.currentWords||0)+delta);c.updatedAt=now;c.createdAt=c.createdAt||now}if(c&&sid){const s=c.sections.find(x=>x.id===sid);if(s){s.currentWords=Math.max(0,Number(s.currentWords||0)+delta);s.updatedAt=now;s.createdAt=s.createdAt||now}}}



function literatureForm(id){const x=state.literature.find(v=>v.id===id)||{title:'',authors:'',year:'',journal:'',doi:'',language:'中文',paperType:'期刊论文',status:'待阅读',usedIn:'',tags:'',favorite:false,citation:'',researchMethod:'',keyConclusion:'',quote:'',notes:''};openSheet(`<h3>${id?'编辑文献':'新增文献卡片'}</h3><div class="field"><label>文献标题</label><input id="f-title" value="${esc(x.title)}"></div><div class="form2"><div class="field"><label>作者</label><input id="f-authors" value="${esc(x.authors)}"></div><div class="field"><label>年份</label><input id="f-year" value="${esc(x.year)}"></div></div><div class="form2"><div class="field"><label>期刊 / 学校 / 来源</label><input id="f-journal" value="${esc(x.journal||'')}"></div><div class="field"><label>DOI</label><input id="f-doi" value="${esc(x.doi||'')}"></div></div><div class="form2"><div class="field"><label>语言</label><select id="f-language">${['中文','英文','其他'].map(s=>`<option ${x.language===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>类型</label><select id="f-paperType">${['期刊论文','硕士论文','博士论文','会议论文','专著','标准/规范','报告','其他'].map(s=>`<option ${x.paperType===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="form2"><div class="field"><label>阅读状态</label><select id="f-status">${['待阅读','粗读','已浏览','已精读','已引用'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>可用于</label><input id="f-used" value="${esc(x.usedIn)}" placeholder="第1章研究现状"></div></div><div class="field"><label>研究方法</label><textarea id="f-method">${esc(x.researchMethod||'')}</textarea></div><div class="field"><label>关键结论</label><textarea id="f-conclusion">${esc(x.keyConclusion||'')}</textarea></div><div class="field"><label>可引用原文 / 页码</label><textarea id="f-quote">${esc(x.quote||'')}</textarea></div><div class="field"><label>标签（逗号分隔）</label><input id="f-tags" value="${esc(x.tags||'')}" placeholder="易发性, 随机森林, 近五年"></div><div class="field"><label>收藏</label><select id="f-favorite"><option value="0" ${!x.favorite?'selected':''}>普通</option><option value="1" ${x.favorite?'selected':''}>★ 重点文献</option></select></div><div class="field"><label>参考文献格式 / 链接</label><textarea id="f-citation">${esc(x.citation||'')}</textarea></div><div class="field"><label>个人笔记</label><textarea id="f-notes">${esc(x.notes||'')}</textarea></div><div class="actions">${id?`<button class="btn danger" onclick="removeItem('literature','${id}')">删除</button>`:''}<button class="btn primary" onclick="saveLiterature('${id||''}')">保存</button></div>`) }
function writingPatternV67(){const hours=Array(24).fill(0),week=Array(7).fill(0);state.writingLogs.forEach(x=>{const h=Number(String(x.createdAt||'').slice(11,13));if(Number.isFinite(h)&&h>=0&&h<24)hours[h]+=Number(x.words||0);const d=dateObj(x.date||x.createdAt);week[d.getDay()]+=Number(x.words||0)});const maxH=Math.max(...hours),hi=hours.indexOf(maxH),maxW=Math.max(...week),wi=week.indexOf(maxW),names=['周日','周一','周二','周三','周四','周五','周六'];return {hour:maxH?`${String(hi).padStart(2,'0')}:00–${String((hi+1)%24).padStart(2,'0')}:00`:'暂无',weekday:maxW?names[wi]:'暂无',streak:streak()}}
function yearHeatmapV67(year=(statsRange==='year'?dateObj(statsAnchor).getFullYear():new Date().getFullYear())){const start=new Date(year,0,1,12),end=new Date(year,11,31,12),vals=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){const day=localISO(d),w=wordsOn(day);vals.push({day,w})}const max=Math.max(1,...vals.map(x=>x.w));return `<div class="section-title"><h2>${year} 写作热力图</h2><span class="sub">颜色越深，写作字数越多</span></div><div class="year-heatmap">${vals.map(x=>{const r=x.w/max,l=x.w===0?'':r<.25?'l1':r<.5?'l2':r<.75?'l3':'l4';return `<div class="heat-cell ${l}" title="${x.day} · ${x.w}字" onclick="statsRange='today';statsAnchor='${x.day}';persistUIState();renderStats()"></div>`}).join('')}</div>`}
function advancedStatsV67(){const p=writingPatternV67(),hist=(state.settings.stageHistory||[]).slice(-5).reverse();return `<div class="section-title"><h2>写作习惯</h2><span class="sub">根据已有写作记录自动计算</span></div><div class="pattern-grid"><div class="pbox"><b>${esc(p.hour)}</b><span>最高产时间段</span></div><div class="pbox"><b>${esc(p.weekday)}</b><span>最高产星期</span></div><div class="pbox"><b>${p.streak} 天</b><span>连续写作</span></div></div>${yearHeatmapV67()}${hist.length?`<div class="section-title"><h2>阶段推进时间线</h2><span class="sub">最近阶段切换</span></div>${hist.map(x=>`<div class="section-mini"><div class="row"><div class="title">${esc(x.stage)}</div><div class="meta">${esc(x.at)}</div></div></div>`).join('')}`:''}`}

