function exportCSV(){let rows=[['模块','业务日期','创建时间','最后修改','完成/解决时间','标题','章节/用途','状态','详情']];state.writingLogs.forEach(x=>rows.push(['写作',x.date,x.createdAt||'',x.updatedAt||'', '',`${x.words}字`,chapterTitle(x.chapterId),`${x.minutes}分钟`,x.note||'']));state.writingRoutes.forEach(x=>rows.push(['写作路线',x.date,x.createdAt||'',x.updatedAt||'',x.completedAt||'',x.title,routeLabel(x),x.done?'已完成':'待完成',x.targetWords?`目标${x.targetWords}字`:'']));state.chapters.forEach(c=>(c.tasks||[]).forEach(t=>rows.push(['章节任务',dateOnly(t.createdAt),t.createdAt||'',t.updatedAt||'',t.completedAt||'',t.title,c.title,t.done?'已完成':'待完成',[t.priority,t.due,t.notes].filter(Boolean).join(' | ')])));state.problems.forEach(x=>rows.push(['问题',dateOnly(x.createdAt),x.createdAt||'',x.updatedAt||'',x.resolvedAt||'',x.title,x.chapter,x.status,[x.description,x.resolution,x.lesson].join(' | ')]));state.feedback.forEach(x=>rows.push(['修改',dateOnly(x.createdAt),x.createdAt||'',x.updatedAt||'',x.completedAt||'',x.title,x.chapter,x.status,x.detail||'']));state.todos.forEach(x=>rows.push(['待办',dateOnly(x.createdAt),x.createdAt||'',x.updatedAt||'',x.completedAt||'',x.title,x.chapter,x.done?'已完成':'待完成',x.notes||'']));state.literature.forEach(x=>rows.push(['文献','',x.createdAt||'',x.updatedAt||'','',x.title,x.usedIn,x.status,[x.authors,x.year,x.journal,x.doi,x.language,x.tags,x.researchMethod,x.keyConclusion].join(' | ')]));state.meetings.forEach(x=>rows.push(['会议',x.date,x.createdAt||'',x.updatedAt||'','',x.topic,x.withWhom,'',x.actions||x.notes||'']));state.figures.forEach(x=>rows.push(['图表','',x.createdAt||'',x.updatedAt||'','',`${x.no||''} ${x.title}`,x.chapter,x.status,x.notes||'']));state.milestones.forEach(x=>rows.push(['节点',x.date,x.createdAt||'',x.updatedAt||'','',x.title,'',x.status,'']));state.versions.forEach(x=>rows.push(['版本',x.date,x.createdAt||'',x.updatedAt||'','',x.name,x.stage,'',x.note||'']));state.defense.forEach(x=>rows.push(['答辩',dateOnly(x.createdAt),x.createdAt||'',x.updatedAt||'',x.completedAt||'',x.title,x.type,x.status,x.notes||'']));const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`学术猫论文数据-V6.8.2-${iso()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}




