function sortResourceArrayV67(arr,type){const a=arr.slice(),stamp=x=>String(x.updatedAt||x.createdAt||x.date||'');if(resourceSort==='new')return a.sort((x,y)=>stamp(y).localeCompare(stamp(x)));if(type==='literature'&&resourceSort==='year')return a.sort((x,y)=>String(y.year||'').localeCompare(String(x.year||'')));if(type==='todos'&&resourceSort==='priority'){const p={高:3,中:2,低:1};return a.sort((x,y)=>(p[y.priority]||0)-(p[x.priority]||0)||String(x.due||'9999').localeCompare(String(y.due||'9999')))}return a}

/* Complete backup: state + active images + snapshots + trash, including image Blobs */
function blobToDataURLV67(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(blob)})}
async function encodeBackupValueV67(v){if(v instanceof Blob){return {__academicCatBlob:true,type:v.type||'application/octet-stream',name:v.name||'',data:await blobToDataURLV67(v)}}if(Array.isArray(v)){const out=[];for(const x of v)out.push(await encodeBackupValueV67(x));return out}if(v&&typeof v==='object'){const o={};for(const [k,x] of Object.entries(v))o[k]=await encodeBackupValueV67(x);return o}return v}
function dataURLToBlobV67(data,type='application/octet-stream',name=''){const [meta,b64]=String(data).split(',');const bin=atob(b64||''),u8=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u8[i]=bin.charCodeAt(i);try{return name?new File([u8],name,{type}):new Blob([u8],{type})}catch(e){return new Blob([u8],{type})}}
async function decodeBackupValueV67(v){if(Array.isArray(v)){const out=[];for(const x of v)out.push(await decodeBackupValueV67(x));return out}if(v&&typeof v==='object'){if(v.__academicCatBlob)return dataURLToBlobV67(v.data,v.type,v.name);const o={};for(const [k,x] of Object.entries(v))o[k]=await decodeBackupValueV67(x);return o}return v}

function formatBytes(n){n=Number(n||0);if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;if(n<1073741824)return `${(n/1048576).toFixed(1)} MB`;return `${(n/1073741824).toFixed(2)} GB`}

