function moveChapterV67(id,dir){const i=state.chapters.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=state.chapters.length)return;[state.chapters[i],state.chapters[j]]=[state.chapters[j],state.chapters[i]];save({render:false});renderChapters();showToast('章节顺序已调整')}
