function saveMeeting(id){const old=state.meetings.find(x=>x.id===id),eventDate=$('#f-date').value,times=auditFields(old,eventDate),meetingId=id||uid();const v={id:meetingId,date:eventDate,topic:$('#f-topic').value.trim(),withWhom:$('#f-with').value.trim(),notes:$('#f-notes').value.trim(),actions:$('#f-actions').value.trim(),nextDate:$('#f-next').value,...times};if(!v.topic)return alert('请填写会议主题');const i=state.meetings.findIndex(x=>x.id===id);if(i>=0)state.meetings[i]=v;else state.meetings.push(v);const mode=$('#f-meeting-link')?.value||'none',actions=v.actions.split(/[\n；;]+/).map(s=>s.trim()).filter(Boolean),now=nowStamp();if(mode==='todos')actions.forEach(title=>{if(!state.todos.some(t=>t.sourceMeetingId===meetingId&&t.title===title))state.todos.push({id:uid(),title,chapter:'',priority:'中',due:v.nextDate||'',notes:`来自导师会议：${v.topic}`,done:false,sourceMeetingId:meetingId,createdAt:now,updatedAt:now,migratedAt:''})});if(mode==='feedback')actions.forEach(title=>{if(!state.feedback.some(t=>t.sourceMeetingId===meetingId&&t.title===title))state.feedback.push({id:uid(),title,chapter:'',source:'导师',round:'会议后修改',priority:'中',status:'待修改',detail:`来自导师会议：${v.topic}`,sourceMeetingId:meetingId,createdAt:now,updatedAt:now,completedAt:''})});if(mode==='problems')actions.forEach(title=>{if(!state.problems.some(t=>t.sourceMeetingId===meetingId&&t.title===title))state.problems.push({id:uid(),title,chapter:'',type:'导师意见',source:'导师提出',description:`来自导师会议：${v.topic}`,status:'未解决',priority:'中',method:'',evidence:v.notes||'',resolution:'',lesson:'',sourceMeetingId:meetingId,createdAt:now,updatedAt:now,resolvedAt:''})});closeSheet();save();if(mode!=='none'&&actions.length)showToast(`已联动生成 ${actions.length} 项记录`)}





